/* @autogenerated */
package net.civeira.phylax.feature.observe.alert;

import java.time.Instant;
import java.util.List;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;

import jakarta.enterprise.context.ApplicationScoped;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.civeira.phylax.feature.observe.observedalertrule.domain.ObservedAlertRule;
import net.civeira.phylax.feature.observe.observedalertrule.domain.gateway.ObservedAlertRuleFilter;
import net.civeira.phylax.feature.observe.observedalertrule.domain.gateway.ObservedAlertRuleQueryRepositoryGateway;

/**
 * Snapshot of the enabled alert rules, in memory like the sources: the writer evaluates them on
 * every batch without touching the database. Reloaded at startup, every minute and shortly after a
 * rule changes.
 */
@ApplicationScoped
@RequiredArgsConstructor
@Slf4j
public class AlertRules {

  /** A rule as the evaluation needs it. */
  public record Rule(String uid, String name, String trigger, String originUid, String minLevel,
      int threshold, int windowMinutes, String channel, String target, int cooldownMinutes,
      Instant mutedUntil) {

    public boolean muted(final Instant now) {
      return null != mutedUntil && now.isBefore(mutedUntil);
    }

    public boolean watches(final String origin) {
      return null == originUid || originUid.equals(origin);
    }
  }

  private static final long PERIOD_SECONDS = 60;

  private final ObservedAlertRuleQueryRepositoryGateway rules;
  private final AlertDispatcher dispatcher;

  private volatile List<Rule> current = List.of();
  private final AtomicBoolean pending = new AtomicBoolean();
  private final AtomicBoolean started = new AtomicBoolean();
  private final ScheduledExecutorService reloader =
      Executors.newSingleThreadScheduledExecutor(r -> {
        Thread thread = new Thread(r, "observe-alert-rules");
        thread.setDaemon(true);
        return thread;
      });

  public List<Rule> all() {
    return current;
  }

  public List<Rule> of(final String trigger) {
    return current.stream().filter(rule -> rule.trigger().equals(trigger)).toList();
  }

  public void start() {
    reload();
    if (started.compareAndSet(false, true)) {
      reloader.scheduleWithFixedDelay(this::reloadQuietly, PERIOD_SECONDS, PERIOD_SECONDS,
          TimeUnit.SECONDS);
    }
  }

  public void stop() {
    reloader.shutdownNow();
  }

  public void invalidate() {
    if (pending.compareAndSet(false, true)) {
      reloader.schedule(() -> {
        pending.set(false);
        reloadQuietly();
      }, 1, TimeUnit.SECONDS);
    }
  }

  public synchronized void reload() {
    List<Rule> loaded = rules.list(ObservedAlertRuleFilter.builder().build()).stream()
        .filter(rule -> Boolean.TRUE.equals(rule.isEnabled())).map(this::toRule).toList();
    for (Rule rule : loaded) {
      if (!dispatcher.available(rule.channel())) {
        log.warn("The alert rule {} uses the channel {}, which is not available"
            + " (email needs multitenant-notification): its alerts are recorded but not notified",
            rule.name(), rule.channel());
      }
    }
    current = loaded;
  }

  private void reloadQuietly() {
    try {
      reload();
    } catch (RuntimeException ex) {
      log.warn("Unable to reload the alert rules: {}", ex.getMessage());
    }
  }

  private Rule toRule(final ObservedAlertRule rule) {
    return new Rule(rule.getUid(), rule.getName(), value(rule.getTrigger()),
        rule.getOriginUid().orElse(null), value(rule.getMinLevel()),
        number(rule.getThreshold(), 10), number(rule.getWindowMinutes(), 5),
        value(rule.getChannel()), rule.getTarget().orElse(null),
        number(rule.getCooldownMinutes(), 30),
        rule.getMutedUntil().map(time -> time.toInstant()).orElse(null));
  }

  /** The option as written in the model (NEW_ISSUE → new-issue). */
  public static String value(final Enum<?> option) {
    return null == option ? null
        : option.name().toLowerCase(java.util.Locale.ROOT).replace('_', '-');
  }

  private static int number(final Integer value, final int fallback) {
    return null == value || value <= 0 ? fallback : value;
  }
}
